SELECT percentile_cont(0.9) within GROUP (ORDER BY (value - valueuom) / NULLIF(ref_range_upper - ref_range_lower, 0)) AS instability_score, COUNT(DISTINCT CASE WHEN deathtime IS NOT NULL THEN labevent_id END) AS mortality_events, AVG(dischtime - admittime) AS average_length_of_stay, AVG(quantity) AS average_critical_lab_events FROM male_labevents_72h; SELECT percentile_cont(0.9) within GROUP (ORDER BY (value - valueuom) / NULLIF(ref_range_upper - ref_range_lower, 0)) AS instability_score, COUNT(DISTINCT CASE WHEN deathtime IS NOT NULL THEN labevent_id END) AS mortality_events, AVG(dischtime - admittime) AS average_length_of_stay, AVG(quantity) AS average_critical_lab_events FROM male_microbiologyevents_72h;